// Read beside the lock: a history request is not a turn and must not queue behind a streaming answer.
async function handleListSessions(
  ws: WebSocket,
  session: ChatSession,
  sessionStore: SessionStore | undefined,
  message: ListSessionsMessage
): Promise<void> {
  try {
    const summaries = (await sessionStore?.listFor?.(session.userId, {limit: message.limit, before: message.before})) ?? [];
    sendJson(ws, {type: 'session_list', sessions: summaries.map(toSummaryFrame)});
  } catch (error) {
    // No store detail reaches the frame or the log beyond the message: both leave the process.
    const detail = error instanceof Error ? error.message : 'Unknown error';
    log.error('ws', 'listing conversations failed', {sessionId: session.sessionId, userId: session.userId, error: detail});
    sendError(ws, ErrorCodes.SERVER_ERROR, 'Failed to list conversations');
  }
}

// A store may hand back a summary that went through JSON, so any shape a Date reads is serialised.
function toSummaryFrame(summary: SessionSummary): SessionSummaryFrame {
  return {
    sessionId: summary.sessionId,
    createdAt: toIso(summary.createdAt),
    updatedAt: toIso(summary.updatedAt),
    entryCount: summary.entryCount,
  };
}

function toIso(value: Date): string {
  return new Date(value).toISOString();
}

